19	// boundaryStore is a caller-supplied service.Store written only against the
20	// exported storage contract. It keeps records in memory like the SQLite
21	// adapter and adds three backend behaviors the contract leaves to the
22	// implementation: a wrapped miss sentinel, a register status returned
23	// together with an error, and a plain backend failure.
24	type boundaryStore struct {
25		records []service.Record
26		byID    map[string]int               // repository\x00digest -> records index
27		tags    map[string]map[string]string // repository -> tag -> digest
28	
29		fault          error                  // non-nil: every method fails with it
30		missWrapper    func(error) error      // non-nil: transforms the lookup miss sentinel
31		registerStatus service.RegisterStatus // status Register returns together with fault
32	}
