41	func boundaryID(repository, digest string) string { return repository + "\x00" + digest }
42	
43	func (b *boundaryStore) miss(err error) error {
44		if b.missWrapper != nil {
45			return b.missWrapper(err)
46		}
47		return err
48	}
49	
50	func (b *boundaryStore) Register(in service.Record) (service.Record, service.RegisterStatus, error) {
51		if b.fault != nil {
52			return service.Record{}, b.registerStatus, b.fault
53		}
54		key := boundaryID(in.Repository, in.Digest)
55		if idx, ok := b.byID[key]; ok {
56			existing := b.records[idx]
57			if existing.Tag == in.Tag &&
58				existing.SignatureVerified == in.SignatureVerified &&
59				existing.RetentionDays == in.RetentionDays &&
60				existing.SizeBytes == in.SizeBytes {
61				return existing, service.StatusDuplicate, nil
62			}
63			return service.Record{}, service.StatusConflict, nil
64		}
65		b.byID[key] = len(b.records)
66		b.records = append(b.records, in)
67		if b.tags[in.Repository] == nil {
68			b.tags[in.Repository] = make(map[string]string)
69		}
70		b.tags[in.Repository][in.Tag] = in.Digest
71		return in, service.StatusCreated, nil
72	}
73	
74	func (b *boundaryStore) ListRecords(repository string) ([]service.Record, error) {
75		if b.fault != nil {
76			return nil, b.fault
77		}
78		var out []service.Record
79		for _, record := range b.records {
80			if record.Repository == repository {
81				out = append(out, record)
82			}
83		}
84		return out, nil
85	}
