87	func (b *boundaryStore) RecordByDigest(repository, digest string) (service.Record, error) {
88		if b.fault != nil {
89			return service.Record{}, b.fault
90		}
91		if idx, ok := b.byID[boundaryID(repository, digest)]; ok {
92			return b.records[idx], nil
93		}
94		return service.Record{}, b.miss(service.ErrRecordNotFound)
95	}
