98		if b.fault != nil {
99			return service.Record{}, b.fault
100		}
101		digest, ok := b.tags[repository][tag]
102		if !ok {
103			return service.Record{}, b.miss(service.ErrRecordNotFound)
104		}
105		return b.records[b.byID[boundaryID(repository, digest)]], nil
106	}
