108	// TestWrappedRecordNotFoundStillMapsTo404 has the backend wrap the miss
109	// sentinel with its own message, as a real adapter would. The service must
110	// still classify it through errors.Is as a miss — 404 ArtifactNotFoundError,
111	// never 503 — while committed data keeps reading back normally.
112	func TestWrappedRecordNotFoundStillMapsTo404(t *testing.T) {
113		st := newBoundaryStore()
114		st.missWrapper = func(err error) error {
115			return fmt.Errorf("boundary backend lookup: %w", err)
116		}
117		router := NewRouterWithStore(st, nil)
118	
119		// Seed one record so the lookups below are legal queries against committed
120		// state whose tag/digest simply does not exist.
121		if recorder := postArtifact(t, router,
122			registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA)); recorder.Code != http.StatusCreated {
123			t.Fatalf("seed register status = %d (%s)", recorder.Code, recorder.Body)
124		}
125	
126		// A miss wrapped by the backend is still a miss: 404, not 503.
127		assertErrorResponse(t, queryByTag(t, router, sequenceRepo, "missing-tag"),
128			http.StatusNotFound, codeNotFound, msgNotFound)
129		assertErrorResponse(t, queryByDigest(t, router, sequenceRepo, testDigestB),
130			http.StatusNotFound, codeNotFound, msgNotFound)
