139	// a backend error for every status variant. The service checks the error
140	// before the status, so the response is always 503 storage_unavailable —
141	// never 201 and never 409 — and the failed register commits nothing.
142	func TestRegisterStatusPlusErrorMapsTo503(t *testing.T) {
143		statuses := map[string]service.RegisterStatus{
144			"created with error":   service.StatusCreated,
145			"duplicate with error": service.StatusDuplicate,
146			"conflict with error":  service.StatusConflict,
147		}
148		for name, status := range statuses {
149			t.Run(name, func(t *testing.T) {
